// Parsear las credenciales exportadas del comando
const input = $input.all()[0].json;

// Extraer el JSON del stdout
const jsonString = input.stdout.match(/\[{.*}\]/s);

if (!jsonString) {
  return [{ json: { error: "No se encontraron credenciales" } }];
}

try {
  const credentials = JSON.parse(jsonString[0]);
  return credentials.map(cred => ({ json: cred }));
} catch (error) {
  return [{ json: { error: `Error parseando credenciales: ${error.message}` } }];
}

// Obtener workflows y credenciales de los items merged
const items = $input.all();

let workflows = [];
let credentials = [];

items.forEach(item => {
  if (item.json.data && Array.isArray(item.json.data)) {
    workflows = item.json.data;
  } else if (item.json.name && item.json.type) {
    credentials.push(item.json);
  }
});

// Construir la URL del POST correctamente
// Obtener solo el dominio base sin paths complicados
const webhookUrl = $execution.resumeUrl || '';
let baseUrl = '';
let postUrl = '';

if (webhookUrl) {
  // Extraer protocolo y dominio (https://qa-n8n.domichat.com.co)
  const urlMatch = webhookUrl.match(/(https?:\/\/[^\/]+)/);
  if (urlMatch) {
    baseUrl = urlMatch[1];
    postUrl = baseUrl + '/webhook/deployment-submit';
  }
}

// Si no se pudo construir, usar relativa
if (!postUrl) {
  postUrl = '/webhook/deployment-submit';
}

console.log('Base URL:', baseUrl);
console.log('POST URL final:', postUrl);

