        const POST_URL = '${postUrl}';
        console.log('POST URL configurada:', POST_URL);

        function toggleAllWorkflows(checkbox) {
            const workflowCheckboxes = document.querySelectorAll('.workflow-checkbox');
            workflowCheckboxes.forEach(cb => cb.checked = checkbox.checked);
        }

        function toggleAllCredentials(checkbox) {
            const credentialCheckboxes = document.querySelectorAll('.credential-checkbox');
            credentialCheckboxes.forEach(cb => cb.checked = checkbox.checked);
        }

        document.getElementById('deploymentForm').addEventListener('submit', async function(e) {
            e.preventDefault();

            const formData = new FormData(this);
            const workflows = formData.getAll('workflows');
            const credentials = formData.getAll('credentials');

            if (workflows.length === 0 && credentials.length === 0) {
                alert('⚠️ Por favor selecciona al menos un workflow o credencial para desplegar.');
                return;
            }

            if (!confirm(\`¿Estás seguro de desplegar \${workflows.length} workflow(s) y \${credentials.length} credencial(es) a Producción?\`)) {
                return;
            }

            // Mostrar loading
            document.getElementById('loading').classList.add('active');
            document.getElementById('submitBtn').disabled = true;

            // Crear el payload JSON
            const payload = {
                workflows: workflows,
                credentials: credentials
            };

            console.log('Enviando payload:', payload);
            console.log('A la URL:', POST_URL);

            try {
                const response = await fetch(POST_URL, {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json'
                    },
                    body: JSON.stringify(payload)
                });

                console.log('Response status:', response.status);

                if (!response.ok) {
                    throw new Error(\`HTTP error! status: \${response.status}\`);
                }

                const html = await response.text();
                document.open();
                document.write(html);
                document.close();
            } catch (error) {
                console.error('Error completo:', error);
                document.getElementById('loading').classList.remove('active');
                document.getElementById('submitBtn').disabled = false;
                alert(\`❌ Error al realizar el despliegue: \${error.message}\\n\\nURL intentada: \${POST_URL}\\n\\nVerifica que el workflow de despliegue esté activo.\`);
            }
        });
    </script>
</body>
