const webhookData = $('🌐 Webhook POST - Recibir Selección').first().json;
const selectedCredentials = webhookData.body.credentials || [];
const credentialsData = $input.all();
const qaCredentials = credentialsData.map(item => item.json).filter(c => !c.error);

if (!selectedCredentials || selectedCredentials.length === 0) {
  return [];
}

const credentialsToDeploy = qaCredentials.filter(cred => 
  selectedCredentials.includes(cred.id)
);

console.log(`✅ Credenciales seleccionadas: ${credentialsToDeploy.length}`);
return credentialsToDeploy.map(cred => ({ json: cred }));

const qaCredentials = $('🔍 Filtrar Credenciales').all();
const prodCredentials = $input.all();
const credentialMapping = [];

for (let i = 0; i < qaCredentials.length && i < prodCredentials.length; i++) {
  const qaId = qaCredentials[i].json.id;
  const prodId = prodCredentials[i].json.id;
  const name = qaCredentials[i].json.name;

  credentialMapping.push({
    oldId: qaId,
    newId: prodId,
    name: name,
    type: qaCredentials[i].json.type
  });
}

console.log('✅ Mapeo creado:', credentialMapping.length, 'credenciales');
return [{ json: { mapping: credentialMapping, hasCredentials: true } }];

const webhookData = $('🌐 Webhook POST - Recibir Selección').first().json;
const selectedWorkflows = webhookData.body.workflows || [];
const qaWorkflowsResponse = $input.first().json;
const qaWorkflows = qaWorkflowsResponse.data || [];

if (!selectedWorkflows || selectedWorkflows.length === 0) {
  return [];
}

const workflowsToDeploy = qaWorkflows.filter(wf => 
  selectedWorkflows.includes(wf.id)
);

console.log(`✅ Workflows seleccionados: ${workflowsToDeploy.length}`);
return workflowsToDeploy.map(wf => ({ json: wf }));

// Obtener mapeo de credenciales
const mappingData = $('🔀 Merge - Mapeo Credenciales').first();
const credentialMapping = mappingData?.json?.mapping || [];
const hasCredentials = mappingData?.json?.hasCredentials || false;

// Obtener workflows
const workflows = $input.all();

if (workflows.length === 0) {
  console.log('⚠️ No hay workflows para preparar');
  return [];
}

console.log(`🔧 Preparando ${workflows.length} workflow(s)`);

const preparedWorkflows = workflows.map(item => {
  const workflow = JSON.parse(JSON.stringify(item.json));

  console.log(`  📋 ${workflow.name}`);

  // Actualizar credenciales si hay mapeo
  if (hasCredentials && credentialMapping.length > 0 && workflow.nodes) {
    workflow.nodes.forEach(node => {
      if (node.credentials) {
        Object.keys(node.credentials).forEach(credType => {
          const oldCredId = node.credentials[credType].id;
          const mapping = credentialMapping.find(m => m.oldId === oldCredId);
          if (mapping) {
            console.log(`    ✓ ${node.name}: ${oldCredId} → ${mapping.newId}`);
            node.credentials[credType].id = mapping.newId;
          }
        });
      }
    });
  }

  // Modificar nombre
  workflow.name = workflow.name + ' [Desde QA]';

  // Limpiar campos
  delete workflow.id;
  delete workflow.createdAt;
  delete workflow.updatedAt;
  delete workflow.versionId;
  delete workflow.shared;
  delete workflow.tags;
  delete workflow.triggerCount;
  delete workflow.error;
  delete workflow.meta;

  // Desactivar
  workflow.active = false;

  return { json: workflow };
});

console.log(`✅ ${preparedWorkflows.length} workflow(s) preparados`);
return preparedWorkflows;

// Workflows desplegados
let deployedWorkflows = [];
try {
  deployedWorkflows = $('📤 Crear Workflows en Prod').all();
} catch(e) {
  console.log('No hay workflows desplegados');
}

// Credenciales desplegadas
