  deployedCredentials = $('📤 Crear Credenciales en Prod').all();
} catch(e) {
  console.log('No hay credenciales desplegadas');
}

// Analizar workflows
const workflowResults = deployedWorkflows.map(item => {
  const hasError = item.json.error || (item.json.statusCode && item.json.statusCode >= 400);
  return {
    name: item.json.name || 'Desconocido',
    id: item.json.id || null,
    status: hasError ? 'error' : 'success',
    error: hasError ? (item.json.error?.message || item.json.message || 'Error desconocido') : null
  };
});

// Analizar credenciales
const credentialResults = deployedCredentials.map(item => {
  const hasError = item.json.error || (item.json.statusCode && item.json.statusCode >= 400);
  return {
    name: item.json.name || 'Desconocido',
    id: item.json.id || null,
    type: item.json.type || 'Desconocido',
    status: hasError ? 'error' : 'success',
    error: hasError ? (item.json.error?.message || item.json.message || 'Error desconocido') : null
  };
});

// Estadísticas
const successfulWorkflows = workflowResults.filter(w => w.status === 'success').length;
const successfulCredentials = credentialResults.filter(c => c.status === 'success').length;

const report = {
  timestamp: new Date().toISOString(),
  summary: {
    workflows: {
      total: workflowResults.length,
      successful: successfulWorkflows,
      failed: workflowResults.length - successfulWorkflows,
      successRate: workflowResults.length > 0 
        ? ((successfulWorkflows / workflowResults.length) * 100).toFixed(1)
        : '0'
    },
    credentials: {
      total: credentialResults.length,
      successful: successfulCredentials,
      failed: credentialResults.length - successfulCredentials,
      successRate: credentialResults.length > 0
        ? ((successfulCredentials / credentialResults.length) * 100).toFixed(1)
        : '0'
    }
  },
  details: {
    workflows: workflowResults,
    credentials: credentialResults
  }
};

console.log('='.repeat(60));
console.log('📊 REPORTE FINAL');
console.log(`Workflows: ${successfulWorkflows}/${workflowResults.length}`);
console.log(`Credenciales: ${successfulCredentials}/${credentialResults.length}`);
console.log('='.repeat(60));

return [{ json: report }];

