const input = $input.all()[0].json;
const jsonString = input.stdout.match(/\[{.*}\]/s);

if (!jsonString) {
  return [{ json: { error: "No se encontraron credenciales" } }];
}

try {
  const credentials = JSON.parse(jsonString[0]);
  return credentials.map(cred => ({ json: cred }));
} catch (error) {
  return [{ json: { error: `Error parseando credenciales: ${error.message}` } }];
}
